/// Returns the default fill value based on the coefficient grid:
/// - If `c` is exactly 1×1, returns that single coefficient.
/// - Otherwise returns `0.0`.
#[requires(c.len() > 0)]
#[requires(forall(|i: usize| i < c.len() ==> c[i].len() > 0))]
#[ensures(
    result ==
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
)]
fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

/// Constructs an output array of the same length as `x` and `y`.
/// - Panics if `x` and `y` differ in length or are empty.
/// - Panics if `c` is empty or any row of `c` is empty.
/// - If `c` is 1×1, fills the output with that single coefficient.
/// - Otherwise fills the output with zeros.
#[requires(x.len() > 0)]
#[requires(x.len() == y.len())]
#[requires(c.len() > 0)]
#[requires(forall(|i: usize| i < c.len() ==> c[i].len() > 0))]
#[ensures(result.len() == x.len())]
#[ensures(forall(|i: usize| i < result.len() ==> result[i] == default_value(&c)))]
fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Validate inputs
    let n = x.len();
    assert!(n > 0, "Input arrays must be non-empty");
    assert!(
        y.len() == n,
        "Input arrays `x` and `y` must have the same length"
    );
    assert!(!c.is_empty(), "Coefficient grid must be non-empty");
    for row in &c {
        assert!(!row.is_empty(), "Rows of the coefficient grid must be non-empty");
    }

    // Compute fill value and produce output
    let fill = default_value(&c);
    // Reinforce that `fill` indeed equals the specification of `default_value`
    assert!(fill == default_value(&c));
    vec![fill; n]
}

